def HasBoundedRows (M : ScalarMatrix 𝕜) : Prop :=
  (∀ k, Summable (fun n => ‖M k n‖)) ∧
  ∃ C : ℝ, ∀ k, (∑' n, ‖M k n‖) ≤ C

