def IsCompactMatrix (M : ScalarMatrix 𝕜) : Prop :=
  HasBoundedRows 𝕜 M ∧
  Tendsto (fun j => matrixNorm 𝕜 (matrixTail 𝕜 M j)) atTop (𝓝 0)

